<section class="panel"><div class="toolbar"><p><?=count($list)?> registros · <?= $page==='facultades'?'Universidad':'Tu facultad'?></p><label class="search-label">Buscar en la tabla<input type="search" id="search" placeholder="Nombre, código, estado…"></label></div><div class="table-wrap"><table id="records"><thead><tr><?php foreach(array_keys($list[0]??[]) as $col):if($col==='id')continue;?><th><?=h(ucfirst(str_replace('_',' ',$col)))?></th><?php endforeach;?><?php if(writable($page,$u)):?><th>Acciones</th><?php endif;?></tr></thead><tbody><?php foreach($list as $r):?><tr><?php foreach($r as $k=>$v):if($k==='id')continue;?><td><?=h($v??'—')?></td><?php endforeach;?><?php if(writable($page,$u)): $raw=rows("SELECT * FROM `$page` WHERE id=?",[$r['id']])[0];?><td><?php if(can_edit($page,$raw,$u)):?><a href="<?=h(app_url('/'))?>?page=<?=h($page)?>&edit=<?=$r['id']?>#editor">Editar</a><?php if(in_array($page,['proyectos','estudiante_proyecto'],true)):?><form class="inline delete-form" method="post" <?= $page==='estudiante_proyecto'?'data-confirm="¿Retirar este vínculo? Se conservarán el estudiante y sus otros proyectos."':'' ?>><?=csrf()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger" name="action" value="delete"><?= $page==='estudiante_proyecto'?'Retirar vínculo':'Eliminar' ?></button></form><?php endif;endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table><?php if(!$list):?><p class="empty">Todavía no hay registros. Comienza con el formulario de esta página.</p><?php endif;?></div></section>
