<?php if($u['rol']==='DECANO'):?><section class="panel"><h2>Presupuesto por período</h2><p>Se suma el presupuesto completo de cada proyecto cuyas fechas se cruzan con el período, una sola vez. No se prorratea.</p><form method="get" class="grid-form"><input type="hidden" name="page" value="reportes"><label>Desde<input type="date" name="desde" required value="<?=h($_GET['desde']??date('Y-01-01'))?>"></label><label>Hasta<input type="date" name="hasta" required value="<?=h($_GET['hasta']??date('Y-12-31'))?>"></label><button>Calcular presupuesto</button></form><?php if(isset($_GET['desde'],$_GET['hasta'])):if(valid_date($_GET['desde'])&&valid_date($_GET['hasta'])&&$_GET['desde']<=$_GET['hasta']){$budget=call_procedure('sp_presupuesto_usuario',[$u['id'],$_GET['desde'],$_GET['hasta']])[0];?><p class="budget">$ <?=number_format((float)$budget['presupuesto'],0,',','.')?> COP</p><p><?=h($budget['proyectos'])?> proyectos en el período.</p><?php }else{?><p class="error">Revisa el período ingresado.</p><?php }endif;?></section><?php endif;?>
